INSERT INTO legacy_import.test_bundles (id, bundle_name, slug, description, price, features, image_url, category, created_at, updated_at) VALUES
('1', 'AMU 9th Entrance Test Series', 'amu-9th-entrance-series', 'Get exam-ready with our comprehensive AMU 9th Test Series Bundle! This exclusive pack is designed to give students complete preparation for the Aligarh Muslim University Class 9 Entrance Exam — combining concept mastery, performance tracking, and real exam experience.', '699.00', '[" 5 Full-Length Mock Tests – Simulate the actual AMU entrance exam pattern and difficulty."," 5 Syllabus-Divided Tests – Chapter-wise & topic-based tests for step-by-step preparation."," Detailed Performance Reports – Analyze your strengths and areas to improve."," Instant Results & Solutions – Get detailed explanations for every question."]', NULL, 'Entrance Exams', '2025-10-14 09:38:11.142055+00', '2025-10-14 09:38:11.142055+00'),
('2', 'AMU 11th Entrance Test Series', 'amu-11th-entrance-series', 'Prepare confidently for the Aligarh Muslim University Class 11 Entrance Exam with our expertly designed AMU 11th Test Series Bundle. This program offers structured syllabus coverage, full-length mock exams, and in-depth performance analysis to help students maximize their scores and secure admission.', '799.00', '["5 Full-Length Mock Tests – Experience real exam-level difficulty and pattern.","5 Syllabus-Divided Tests – Topic-wise tests for systematic and focused preparation.","Detailed Performance Reports – Identify strengths, weaknesses, and improvement areas.","Instant Results & Detailed Solutions – Clear explanations for every question.","Based on Latest AMU 11th Entrance Syllabus – Stay fully aligned with the current exam pattern."]', NULL, 'Entrance Exams', '2026-02-04 06:43:40.586863+00', '2026-02-04 06:43:40.586863+00')
