-- Seed the exam collections.
ON CONFLICT (id) DO UPDATE SET slug=EXCLUDED.slug,name=EXCLUDED.name,description=EXCLUDED.description,subjects=EXCLUDED.subjects,status=EXCLUDED.status,sort_order=EXCLUDED.sort_order;

-- Preserve source test IDs. All imported rows are published so the existing catalog is visible; review and unpublish drafts from /admin.
SELECT id, CASE WHEN lower(test_name) LIKE '%11th%' THEN 'amu-11' ELSE 'amu-9' END, test_name, COALESCE(duration_minutes,60), COALESCE(subject_topic,''), COALESCE(instructions,''), CASE WHEN lower(COALESCE(test_category,''))='practice' THEN 'demo' WHEN lower(COALESCE(test_category,''))='demo' THEN 'demo' WHEN lower(COALESCE(test_category,''))='upcoming' THEN 'upcoming' ELSE 'standard' END, date_scheduled::timestamptz, true, COALESCE(created_at,now())
FROM legacy_import.tests
ON CONFLICT (id) DO UPDATE SET exam_id=EXCLUDED.exam_id,test_name=EXCLUDED.test_name,duration_minutes=EXCLUDED.duration_minutes,subject_topic=EXCLUDED.subject_topic,instructions=EXCLUDED.instructions,test_category=EXCLUDED.test_category,date_scheduled=EXCLUDED.date_scheduled,published=EXCLUDED.published,created_at=EXCLUDED.created_at;

-- Convert legacy option arrays [0..3] into the new keyed {a,b,c,d} shape.
SELECT id,test_id,question_text,jsonb_build_object('a',options->0,'b',options->1,'c',options->2,'d',options->3),lower(correct_option),COALESCE(marks,1),NULLIF(image_url,'')
FROM legacy_import.questions
WHERE jsonb_typeof(options)='array' AND jsonb_array_length(options)>=4
ON CONFLICT (id) DO UPDATE SET test_id=EXCLUDED.test_id,question_text=EXCLUDED.question_text,options=EXCLUDED.options,correct_option=EXCLUDED.correct_option,marks=EXCLUDED.marks,image_url=EXCLUDED.image_url;

-- Preserve bundle IDs. The legacy dump has no bundle-to-test join table, so do not guess membership. Add it in /admin/bundles.
SELECT id,CASE WHEN lower(bundle_name) LIKE '%11th%' THEN 'amu-11' ELSE 'amu-9' END,bundle_name,COALESCE(description,''),price,ARRAY(SELECT jsonb_array_elements_text(COALESCE(features,'[]'::jsonb))),true
FROM legacy_import.test_bundles
ON CONFLICT (id) DO UPDATE SET exam_id=EXCLUDED.exam_id,bundle_name=EXCLUDED.bundle_name,description=EXCLUDED.description,price=EXCLUDED.price,features=EXCLUDED.features,published=EXCLUDED.published;

-- Create a UUID mapping when a legacy student signs in with the same email.
ALTER TABLE legacy_import.users ADD COLUMN IF NOT EXISTS auth_user_id uuid;
CREATE OR REPLACE FUNCTION private.link_legacy_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE legacy_id integer; auth_email text;
BEGIN
 SELECT lower(trim(email)) INTO auth_email FROM auth.users WHERE id=NEW.id;
 SELECT id INTO legacy_id FROM legacy_import.users WHERE lower(trim(email_or_phone))=auth_email ORDER BY id LIMIT 1;
 IF legacy_id IS NULL THEN RETURN NEW; END IF;
 UPDATE legacy_import.users SET auth_user_id=NEW.id WHERE id=legacy_id;
 UPDATE public.profiles SET full_name=COALESCE(NULLIF(lu.full_name,''),public.profiles.full_name),school_name=COALESCE(lu.school_name,''),dob=lu.dob,gender=COALESCE(lu.gender,''),mobile_number=COALESCE(lu.mobile_number,''),city=COALESCE(lu.city,''),state=COALESCE(lu.state,''),country=COALESCE(lu.country,'') FROM legacy_import.users lu WHERE lu.id=legacy_id AND public.profiles.id=NEW.id;
 RETURN NEW;
END; $$;
DROP TRIGGER IF EXISTS link_legacy_profile_after_insert ON public.profiles;
CREATE TRIGGER link_legacy_profile_after_insert AFTER INSERT ON public.profiles FOR EACH ROW EXECUTE FUNCTION private.link_legacy_profile();
REVOKE ALL ON FUNCTION private.link_legacy_profile() FROM PUBLIC,anon,authenticated;

-- Reset identity sequences after preserving the legacy integer IDs.
SELECT setval(pg_get_serial_sequence('public.tests','id'), COALESCE((SELECT max(id) FROM public.tests),0)+1, false);
SELECT setval(pg_get_serial_sequence('public.questions','id'), COALESCE((SELECT max(id) FROM public.questions),0)+1, false);
SELECT setval(pg_get_serial_sequence('public.bundles','id'), COALESCE((SELECT max(id) FROM public.bundles),0)+1, false);

COMMIT;

-- Legacy OTPs are intentionally excluded: they are expired authentication secrets.
-- Legacy users, results, attempts, and progress are preserved in legacy_import.
-- After a user signs in, verify their row: SELECT * FROM legacy_import.users WHERE auth_user_id IS NOT NULL;
